1	import type {
2	  ArgumentMetadata,
3	  ContextType,
4	  RouteParamMetadata,
5	} from '@nestjs/common';
6	import {
7	  type CanActivate,
8	  BadRequestException,
9	  ForbiddenException,
10	  type HttpServer,
11	  type ParamData,
12	  type PipeTransform,
13	  type RequestMethod,
14	  SSE_ABORT_CONTROLLER,
15	} from '@nestjs/common';
16	import {
17	  AGGREGATE_PARAM_ERRORS_METADATA,
18	  type Controller,
19	  CUSTOM_ROUTE_ARGS_METADATA,
20	  HEADERS_METADATA,
21	  HTTP_CODE_METADATA,
22	  isEmptyArray,
23	  isString,
24	  REDIRECT_METADATA,
25	  RENDER_METADATA,
26	  ROUTE_ARGS_METADATA,
27	  RouteParamtypes,
28	  SSE_METADATA,
29	} from '@nestjs/common/internal';
30	import type { StandardSchemaV1 } from '@standard-schema/spec';
31	import { IncomingMessage } from 'http';
32	import { Observable } from 'rxjs';
33	import {
34	  FORBIDDEN_MESSAGE,
35	  GuardsConsumer,
36	  GuardsContextCreator,
37	} from '../guards/index.js';
38	import { ContextUtils } from '../helpers/context-utils.js';
39	import { ExecutionContextHost } from '../helpers/execution-context-host.js';
40	import {
41	  HandleResponseFn,
42	  HandlerMetadata,
43	  HandlerMetadataStorage,
44	  HandlerResponseBasicFn,
45	} from '../helpers/handler-metadata-storage.js';
46	import { STATIC_CONTEXT } from '../injector/constants.js';
47	import { InterceptorsConsumer } from '../interceptors/interceptors-consumer.js';
48	import { InterceptorsContextCreator } from '../interceptors/interceptors-context-creator.js';
49	import { PipesConsumer } from '../pipes/pipes-consumer.js';
50	import { PipesContextCreator } from '../pipes/pipes-context-creator.js';
51	import { IRouteParamsFactory } from './interfaces/route-params-factory.interface.js';
52	import {
53	  CustomHeader,
54	  RedirectResponse,
55	  RouterResponseController,
56	} from './router-response-controller.js';
57	import { HeaderStream } from './sse-stream.js';
58	
59	export interface ParamProperties {
60	  index: number;
61	  type: RouteParamtypes | string;
62	  data: ParamData;
63	  pipes: PipeTransform[];
64	  extractValue: <TRequest, TResponse>(
65	    req: TRequest,
66	    res: TResponse,
67	    next: Function,
68	  ) => any;
69	  schema?: StandardSchemaV1;
70	}
71	
72	export class RouterExecutionContext {
73	  private readonly handlerMetadataStorage = new HandlerMetadataStorage();
74	  private readonly contextUtils = new ContextUtils();
75	  private readonly responseController: RouterResponseController;
76	
77	  constructor(
78	    private readonly paramsFactory: IRouteParamsFactory,
79	    private readonly pipesContextCreator: PipesContextCreator,
80	    private readonly pipesConsumer: PipesConsumer,
81	    private readonly guardsContextCreator: GuardsContextCreator,
82	    private readonly guardsConsumer: GuardsConsumer,
83	    private readonly interceptorsContextCreator: InterceptorsContextCreator,
84	    private readonly interceptorsConsumer: InterceptorsConsumer,
85	    readonly applicationRef: HttpServer,
86	  ) {
87	    this.responseController = new RouterResponseController(applicationRef);
88	  }
89	
90	  public create(
91	    instance: Controller,
92	    callback: (...args: any[]) => unknown,
93	    methodName: string,
94	    moduleKey: string,
95	    requestMethod: RequestMethod,
96	    contextId = STATIC_CONTEXT,
97	    inquirerId?: string,
98	  ) {
99	    const contextType: ContextType = 'http';
100	    const {
101	      argsLength,
102	      fnHandleResponse,
103	      isSseHandler,
104	      paramtypes,
105	      getParamsMetadata,
106	      httpStatusCode,
107	      responseHeaders,
108	      hasCustomHeaders,
109	      aggregateParamErrors,
110	    } = this.getMetadata(
111	      instance,
112	      callback,
113	      methodName,
114	      moduleKey,
115	      requestMethod,
116	      contextType,
117	    );
118	
119	    const paramsOptions = this.contextUtils.mergeParamsMetatypes(
120	      getParamsMetadata(moduleKey, contextId, inquirerId),
121	      paramtypes,
122	    );
123	    const pipes = this.pipesContextCreator.create(
124	      instance,
125	      callback,
126	      moduleKey,
127	      contextId,
128	      inquirerId,
129	    );
130	    const guards = this.guardsContextCreator.create(
131	      instance,
132	      callback,
133	      moduleKey,
134	      contextId,
135	      inquirerId,
136	    );
137	    const interceptors = this.interceptorsContextCreator.create(
138	      instance,
139	      callback,
140	      moduleKey,
141	      contextId,
142	      inquirerId,
143	    );
144	
145	    const fnCanActivate = this.createGuardsFn(
146	      guards,
147	      instance,
148	      callback,
149	      contextType,
150	    );
151	    const fnApplyPipes = this.createPipesFn(
152	      pipes,
153	      paramsOptions,
154	      aggregateParamErrors,
155	    );
156	
157	    const handler =
158	      <TRequest, TResponse>(
159	        args: any[],
160	        req: TRequest,
161	        res: TResponse,
162	        next: Function,
163	      ) =>
164	      async () => {
165	        fnApplyPipes && (await fnApplyPipes(args, req, res, next));
166	        return callback.apply(instance, args);
167	      };
168	
169	    return async <TRequest, TResponse>(
170	      req: TRequest,
171	      res: TResponse,
172	      next: Function,
173	    ) => {
174	      const args = this.contextUtils.createNullArray(argsLength);
175	      fnCanActivate && (await fnCanActivate([req, res, next]));
176	
177	      this.responseController.setStatus(res, httpStatusCode);
178	      hasCustomHeaders &&
179	        this.responseController.setHeaders(res, responseHeaders);
180	
181	      if (isSseHandler) {
182	        // Attach a per-request AbortController before the handler runs so async
183	        // @Sse() handlers can observe client disconnects via @SseSignal() during
184	        // their setup. The controller is aborted in RouterResponseController.sse()
185	        // when the underlying connection closes.
186	        this.attachSseAbortSignal(req);
187	      }
188	
189	      const resultOrDeferred = this.interceptorsConsumer.intercept(
190	        interceptors,
191	        [req, res, next],
192	        instance,
193	        callback,
194	        handler(args, req, res, next),
195	        contextType,
196	      );
197	      const result = isSseHandler ? resultOrDeferred : await resultOrDeferred;
198	      await (fnHandleResponse as HandlerResponseBasicFn)(result, res, req);
199	    };
200	  }
201	
202	  public getMetadata<TContext extends ContextType = ContextType>(
203	    instance: Controller,
204	    callback: (...args: any[]) => any,
205	    methodName: string,
206	    moduleKey: string,
207	    requestMethod: RequestMethod,
208	    contextType: TContext,
209	  ): HandlerMetadata {
210	    const cacheMetadata = this.handlerMetadataStorage.get(instance, methodName);
211	    if (cacheMetadata) {
212	      return cacheMetadata;
213	    }
214	    const metadata =
215	      this.contextUtils.reflectCallbackMetadata(
216	        instance,
217	        methodName,
218	        ROUTE_ARGS_METADATA,
219	      ) || {};
220	    const keys = Object.keys(metadata);
221	    const argsLength = this.contextUtils.getArgumentsLength(keys, metadata);
222	    const paramtypes = this.contextUtils.reflectCallbackParamtypes(
223	      instance,
224	      methodName,
225	    );
226	
227	    const contextFactory = this.contextUtils.getContextFactory(
228	      contextType,
229	      instance,
230	      callback,
231	    );
232	    const getParamsMetadata = (
233	      moduleKey: string,
234	      contextId = STATIC_CONTEXT,
235	      inquirerId?: string,
236	    ) =>
237	      this.exchangeKeysForValues(
238	        keys,
239	        metadata,
240	        moduleKey,
241	        contextId,
242	        inquirerId,
243	        contextFactory,
244	      );
245	
246	    const paramsMetadata = getParamsMetadata(moduleKey);
247	    const isResponseHandled = this.isResponseHandled(
248	      instance,
249	      methodName,
250	      paramsMetadata,
251	    );
252	
253	    const httpRedirectResponse = this.reflectRedirect(callback);
254	    const fnHandleResponse = this.createHandleResponseFn(
255	      callback,
256	      isResponseHandled,
257	      httpRedirectResponse,
258	    );
259	    const isSseHandler = !!this.reflectSse(callback);
260	
261	    const httpCode = this.reflectHttpStatusCode(callback);
262	    const httpStatusCode =
263	      httpCode ?? this.responseController.getStatusByMethod(requestMethod);
264	
265	    const aggregateParamErrors = this.reflectAggregateParamErrors(callback);
266	
267	    const responseHeaders = this.reflectResponseHeaders(callback);
268	    const hasCustomHeaders = !isEmptyArray(responseHeaders);
269	    const handlerMetadata: HandlerMetadata = {
270	      argsLength,
271	      fnHandleResponse,
272	      isSseHandler,
273	      paramtypes,
274	      getParamsMetadata,
275	      httpStatusCode,
276	      hasCustomHeaders,
277	      responseHeaders,
278	      aggregateParamErrors,
279	    };
280	    this.handlerMetadataStorage.set(instance, methodName, handlerMetadata);
281	    return handlerMetadata;
282	  }
283	
284	  public reflectRedirect(
285	    callback: (...args: unknown[]) => unknown,
286	  ): RedirectResponse {
287	    return Reflect.getMetadata(REDIRECT_METADATA, callback);
288	  }
289	
290	  public reflectHttpStatusCode(
291	    callback: (...args: unknown[]) => unknown,
292	  ): number {
293	    return Reflect.getMetadata(HTTP_CODE_METADATA, callback);
294	  }
295	
296	  public reflectRenderTemplate(
297	    callback: (...args: unknown[]) => unknown,
298	  ): string {
299	    return Reflect.getMetadata(RENDER_METADATA, callback);
300	  }
301	
302	  public reflectResponseHeaders(
303	    callback: (...args: unknown[]) => unknown,
304	  ): CustomHeader[] {
305	    return Reflect.getMetadata(HEADERS_METADATA, callback) || [];
306	  }
307	
308	  public reflectSse(callback: (...args: unknown[]) => unknown): string {
309	    return Reflect.getMetadata(SSE_METADATA, callback);
310	  }
311	
312	  public reflectAggregateParamErrors(
313	    callback: (...args: unknown[]) => unknown,
314	  ): boolean {
315	    return !!Reflect.getMetadata(AGGREGATE_PARAM_ERRORS_METADATA, callback);
316	  }
317	
318	  public exchangeKeysForValues(
319	    keys: string[],
320	    metadata: Record<number, RouteParamMetadata>,
321	    moduleContext: string,
322	    contextId = STATIC_CONTEXT,
323	    inquirerId?: string,
324	    contextFactory?: (args: unknown[]) => ExecutionContextHost,
325	  ): ParamProperties[] {
326	    this.pipesContextCreator.setModuleContext(moduleContext);
327	
328	    return keys.map(key => {
329	      const { index, data, pipes: pipesCollection, schema } = metadata[key];
330	      const pipes = this.pipesContextCreator.createConcreteContext(
331	        pipesCollection,
332	        contextId,
333	        inquirerId,
334	      );
335	      const type = this.contextUtils.mapParamType(key);
336	
337	      if (key.includes(CUSTOM_ROUTE_ARGS_METADATA)) {
338	        const { factory } = metadata[key];
339	        const customExtractValue = this.contextUtils.getCustomFactory(
340	          factory,
341	          data,
342	          contextFactory!,
343	        );
344	        return {
345	          index,
346	          extractValue: customExtractValue,
347	          type,
348	          data,
349	          pipes,
350	          schema,
351	        };
352	      }
353	      const numericType = Number(type);
354	      const extractValue = <TRequest, TResponse>(
355	        req: TRequest,
356	        res: TResponse,
357	        next: Function,
358	      ) =>
359	        this.paramsFactory.exchangeKeyForValue(numericType, data, {
360	          req: req as Record<string, any>,
361	          res,
362	          next,
363	        });
364	      return { index, extractValue, type: numericType, data, pipes, schema };
365	    });
366	  }
367	
368	  public async getParamValue<T>(
369	    value: T,
370	    metadata: ArgumentMetadata,
371	    pipes: PipeTransform[],
372	  ): Promise<unknown> {
373	    if (!isEmptyArray(pipes)) {
374	      return this.pipesConsumer.apply(value, metadata, pipes);
375	    }
376	    return value;
377	  }
378	
379	  public isPipeable(type: number | string): boolean {
380	    return (
381	      type === RouteParamtypes.BODY ||
382	      type === RouteParamtypes.RAW_BODY ||
383	      type === RouteParamtypes.QUERY ||
384	      type === RouteParamtypes.PARAM ||
385	      type === RouteParamtypes.FILE ||
386	      type === RouteParamtypes.FILES ||
387	      isString(type)
388	    );
389	  }
390	
391	  public isParamErrorAggregated(type: number | string): boolean {
392	    return type === RouteParamtypes.PARAM || type === RouteParamtypes.QUERY;
393	  }
394	
395	  public createGuardsFn<TContext extends string = ContextType>(
396	    guards: CanActivate[],
397	    instance: Controller,
398	    callback: (...args: any[]) => any,
399	    contextType?: TContext,
400	  ): ((args: any[]) => Promise<void>) | null {
401	    const canActivateFn = async (args: any[]) => {
402	      const canActivate = await this.guardsConsumer.tryActivate<TContext>(
403	        guards,
404	        args,
405	        instance,
406	        callback,
407	        contextType,
408	      );
409	      if (!canActivate) {
410	        throw new ForbiddenException(FORBIDDEN_MESSAGE);
411	      }
412	    };
413	    return guards.length ? canActivateFn : null;
414	  }
415	
416	  public createPipesFn(
417	    pipes: PipeTransform[],
418	    paramsOptions: (ParamProperties & { metatype?: any })[],
419	    aggregateParamErrors = false,
420	  ) {
421	    const resolveParamValue = async <TRequest, TResponse>(
422	      param: ParamProperties & { metatype?: any },
423	      args: any[],
424	      req: TRequest,
425	      res: TResponse,
426	      next: Function,
427	    ) => {
428	      const {
429	        index,
430	        extractValue,
431	        type,
432	        data,
433	        metatype,
434	        pipes: paramPipes,
435	        schema,
436	      } = param;
437	      const value = extractValue(req, res, next);
438	
439	      args[index] = this.isPipeable(type)
440	        ? await this.getParamValue(
441	            value,
442	            { metatype, type, data, schema } as ArgumentMetadata,
443	            pipes.concat(paramPipes),
444	          )
445	        : value;
446	    };
447	
448	    const pipesFn = async <TRequest, TResponse>(
449	      args: any[],
450	      req: TRequest,
451	      res: TResponse,
452	      next: Function,
453	    ) => {
454	      if (!aggregateParamErrors) {
455	        await Promise.all(
456	          paramsOptions.map(param =>
457	            resolveParamValue(param, args, req, res, next),
458	          ),
459	        );
460	        return;
461	      }
462	
463	      // @Param()/@Query() pipes are executed serially, in parameter-index
464	      // order, and their rejections are collected and rethrown as a single
465	      // BadRequestException. Pipes bound to any other parameter keep the
466	      // existing fail-fast path (their errors propagate immediately).
467	      const orderedParams = [...paramsOptions].sort(
468	        (a, b) => a.index - b.index,
469	      );
470	      const messages: unknown[] = [];
471	      for (const param of orderedParams) {
472	        if (!this.isParamErrorAggregated(param.type)) {
473	          await resolveParamValue(param, args, req, res, next);
474	          continue;
475	        }
476	        try {
477	          await resolveParamValue(param, args, req, res, next);
478	        } catch (err) {
479	          // Only parameter validation errors are aggregated; any other
480	          // exception keeps the existing fail-fast path.
481	          if (!(err instanceof BadRequestException)) {
482	            throw err;
483	          }
484	          messages.push(...this.extractParamErrorMessages(err));
485	        }
486	      }
487	      if (messages.length > 0) {
488	        throw new BadRequestException(messages);
489	      }
490	    };
491	    return paramsOptions.length ? pipesFn : null;
492	  }
493	
494	  private extractParamErrorMessages(error: BadRequestException): unknown[] {
495	    const response = error.getResponse();
496	    if (typeof response === 'object' && response !== null) {
497	      const { message } = response as Record<string, unknown>;
498	      if (message !== undefined) {
499	        return Array.isArray(message) ? message : [message];
500	      }
501	    }
502	    return [response];
503	  }
504	
505	  public createHandleResponseFn(
506	    callback: (...args: unknown[]) => unknown,
507	    isResponseHandled: boolean,
508	    redirectResponse?: RedirectResponse,
509	    httpStatusCode?: number,
510	  ): HandleResponseFn {
511	    const renderTemplate = this.reflectRenderTemplate(callback);
512	    if (renderTemplate) {
513	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
514	        return await this.responseController.render(
515	          result,
516	          res,
517	          renderTemplate,
518	        );
519	      };
520	    }
521	    if (redirectResponse && isString(redirectResponse.url)) {
522	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
523	        await this.responseController.redirect(result, res, redirectResponse);
524	      };
525	    }
526	    const isSseHandler = !!this.reflectSse(callback);
527	    if (isSseHandler) {
528	      return async <
529	        TResult extends Observable<unknown> = any,
530	        TResponse extends HeaderStream = any,
531	        TRequest extends IncomingMessage = any,
532	      >(
533	        result: TResult,
534	        res: TResponse,
535	        req: TRequest,
536	      ) => {
537	        const rawResponse = (res as { raw?: TResponse }).raw ?? res;
538	        await this.responseController.sse(
539	          result,
540	          rawResponse,
541	          (req as any).raw || req,
542	          {
543	            additionalHeaders: res.getHeaders?.(),
544	            statusCode:
545	              (res as { statusCode?: number }).statusCode ??
546	              (rawResponse as { statusCode?: number }).statusCode,
547	          },
548	        );
549	      };
550	    }
551	    return async <TResult, TResponse>(result: TResult, res: TResponse) => {
552	      result = await this.responseController.transformToResult(result);
